//! Build script for `dw-signatures`.
//!
//! Reads all `*.toml` files under `assets/public-signatures/`, parses
//! them into `SignatureSpec` structs, and generates a Rust source file
//! `signatures_gen.rs` in `OUT_DIR` containing a `pub const SIGNATURES:
//! &[SignatureSpec] = &[...];` array.
//!
//! The generated file is `include!`-d by `src/db.rs` at compile time,
//! so the signature data is embedded in the binary with no runtime file
//! dependency.

// Build scripts legitimately panic on invalid input — that's how build
// errors are reported to the developer.
#![allow(clippy::panic, clippy::expect_used)]

use std::collections::HashSet;
use std::path::PathBuf;

use serde::Deserialize;

#[derive(Debug, Clone, Deserialize)]
struct SignaturesFile {
    signature: Vec<SignatureToml>,
}

#[derive(Debug, Clone, Deserialize)]
struct SignatureToml {
    extension: String,
    #[serde(default)]
    mime: Option<String>,
    header_offset: u32,
    header_magic: String,
    #[serde(default)]
    tail_offset: u32,
    #[serde(default)]
    tail_magic: Option<String>,
    #[serde(default)]
    min_size: u64,
    #[serde(default)]
    max_size: u64,
    #[serde(default = "default_weight")]
    weight: u16,
    source: String,
}

fn default_weight() -> u16 {
    500
}

#[derive(Debug)]
struct ParsedMagic {
    /// (byte, mask) pairs: None mask = wildcard (match any byte).
    bytes: Vec<Option<u8>>,
}

fn parse_magic(s: &str) -> Result<ParsedMagic, String> {
    let mut bytes = Vec::new();
    for token in s.split_whitespace() {
        if token == "??" {
            bytes.push(None);
        } else if token.len() == 2 {
            let byte = u8::from_str_radix(token, 16)
                .map_err(|e| format!("invalid hex byte '{token}': {e}"))?;
            bytes.push(Some(byte));
        } else {
            return Err(format!(
                "invalid magic token '{token}' (expected ?? or 2 hex digits)"
            ));
        }
    }
    Ok(ParsedMagic { bytes })
}

fn main() {
    println!("cargo:rerun-if-changed=assets/public-signatures");

    let assets_dir = PathBuf::from("assets/public-signatures");
    let mut toml_files: Vec<PathBuf> = Vec::new();
    if assets_dir.exists() {
        for entry in std::fs::read_dir(&assets_dir).expect("read assets dir") {
            let entry = entry.expect("read dir entry");
            let path = entry.path();
            if path.extension().is_some_and(|e| e == "toml") {
                toml_files.push(path);
            }
        }
    }
    toml_files.sort();

    let mut signatures: Vec<SignatureToml> = Vec::new();
    let mut seen_sources: HashSet<String> = HashSet::new();

    for toml_path in &toml_files {
        let content = std::fs::read_to_string(toml_path)
            .unwrap_or_else(|e| panic!("read {}: {e}", toml_path.display()));
        let docs: SignaturesFile = toml::from_str(&content)
            .unwrap_or_else(|e| panic!("parse {}: {e}", toml_path.display()));
        for sig in docs.signature {
            // Validate the magic strings parse
            let _ = parse_magic(&sig.header_magic)
                .unwrap_or_else(|e| panic!("{}: invalid header_magic: {e}", toml_path.display()));
            if let Some(ref tail) = sig.tail_magic {
                let _ = parse_magic(tail)
                    .unwrap_or_else(|e| panic!("{}: invalid tail_magic: {e}", toml_path.display()));
            }
            if !seen_sources.insert(sig.source.clone()) {
                // Duplicate source citation is fine — multiple sigs can cite the same source
            }
            signatures.push(sig);
        }
    }

    eprintln!(
        "[dw-signatures] Compiled {} signatures from {} TOML files",
        signatures.len(),
        toml_files.len()
    );

    // Generate the Rust source file.
    let out_dir = std::env::var("OUT_DIR").expect("OUT_DIR not set");
    let out_path = PathBuf::from(&out_dir).join("signatures_gen.rs");

    let mut code = String::new();
    code.push_str("// AUTO-GENERATED by build.rs. Do not edit.\n");
    code.push_str("// Source: assets/public-signatures/*.toml\n\n");
    code.push_str("pub const SIGNATURES: &[SignatureSpec] = &[\n");

    for sig in &signatures {
        let header = parse_magic(&sig.header_magic).expect("validated above");
        let tail = sig
            .tail_magic
            .as_deref()
            .map(parse_magic)
            .transpose()
            .expect("validated above");

        let header_bytes: Vec<String> = header
            .bytes
            .iter()
            .map(|b| match b {
                Some(v) => format!("Some({v}u8)"),
                None => "None".to_string(),
            })
            .collect();
        let header_bytes_str = header_bytes.join(", ");

        let tail_bytes_str = match &tail {
            Some(t) => {
                let tail_bytes: Vec<String> = t
                    .bytes
                    .iter()
                    .map(|b| match b {
                        Some(v) => format!("Some({v}u8)"),
                        None => "None".to_string(),
                    })
                    .collect();
                format!("Some(&[{}])", tail_bytes.join(", "))
            }
            None => "None".to_string(),
        };

        code.push_str(&format!(
            "    SignatureSpec {{\n\
             \x20       extension: {:?},\n\
             \x20       mime: {},\n\
             \x20       header_offset: {},\n\
             \x20       header_magic: &[{}],\n\
             \x20       tail_offset: {},\n\
             \x20       tail_magic: {},\n\
             \x20       min_size: {},\n\
             \x20       max_size: {},\n\
             \x20       weight: {},\n\
             \x20       source: {:?},\n\
             \x20   }},\n",
            sig.extension,
            sig.mime
                .as_ref()
                .map(|m| format!("Some({m:?})"))
                .unwrap_or("None".to_string()),
            sig.header_offset,
            header_bytes_str,
            sig.tail_offset,
            tail_bytes_str,
            sig.min_size,
            sig.max_size,
            sig.weight,
            sig.source,
        ));
    }

    code.push_str("];\n");

    std::fs::write(&out_path, code).expect("write signatures_gen.rs");
}
